// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Img,
} from '../remotionShim';
// Google Fonts Loader (Migrated to direct subpath imports)
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadInter = makeLoadFont('Inter');
const loadRoboto = makeLoadFont('Roboto');

const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoFamily } = loadRoboto();

// Zod Schema


export type ExamSchedulePromoProps = Record<string, any>;

const ExamSchedulePromo: React.FC<ExamSchedulePromoProps> = ({
  backgroundColor = "#02040a",
  transparentBackground = false,
  durationInSeconds = 8,
  gradientStart = "#02040a", // Deep Space Black
  gradientEnd = "#102a45",   // Cosmic Blue/Navy
  titleText = "PERPLEXITY",
  titleFont = "Playfair Display",
  subtitleText = "Ask. Research. Trusted Answers",
  screenshotUrl = "https://malloy.blob.core.windows.net/web/testing/460x996bb (2).webp",
  phoneBorderColor = "#2ce0d0", // Teal/Cyan accent from reference logo
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Aspect Ratio Check for Responsiveness
  const isPortrait = height > width;

  // Background Handling - Switched to Radial for "Glow" effect
  const finalBg = transparentBackground
    ? "transparent"
    : `radial-gradient(circle at 50% 100%, ${gradientEnd} 0%, ${gradientStart} 80%)`;

  // Animation - Phone
  const phoneEntrance = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 45, mass: 1.4 },
    durationInFrames: 55,
    delay: 5,
  });

  const hoverTime = frame / 35;
  const hoverY = Math.sin(hoverTime) * 12; 
  const hoverRotate = Math.cos(hoverTime) * 1.5;

  const phoneRotateY = interpolate(phoneEntrance, [0, 1], [-65, isPortrait ? -10 : -15]) + hoverRotate; 
  const phoneRotateX = interpolate(phoneEntrance, [0, 1], [35, isPortrait ? 5 : 10]) + (hoverRotate * 0.5); 
  const phoneTranslateY = interpolate(phoneEntrance, [0, 1], [height * 0.6, 0]) + hoverY;
  const phoneScale = interpolate(phoneEntrance, [0, 1], [0.8, 1]);
  const phoneOpacity = interpolate(phoneEntrance, [0, 0.4], [0, 1]);

  // Animation - Text
  const textEntrance = spring({
    frame,
    fps,
    config: { damping: 15 },
    delay: 20, 
  });

  const textTranslateX = interpolate(textEntrance, [0, 1], [isPortrait ? 0 : -50, 0]);
  const textTranslateY = interpolate(textEntrance, [0, 1], [isPortrait ? 50 : 0, 0]);
  const textOpacity = interpolate(textEntrance, [0, 1], [0, 1]);

  // Font Selection Logic
  const getTitleFontFamily = () => {
    switch (titleFont) {
      case "Inter":
        return interFamily;
      case "Roboto":
        return robotoFamily;
      case "Playfair Display":
      default:
        return playfairFamily;
    }
  };

  // Dimensions & Responsive Settings
  const phoneWidth = isPortrait ? width * 0.55 : height * 0.45;
  const phoneHeight = phoneWidth * (0.85 / 0.45); // Maintains consistent aspect ratio
  const thickness = Math.max(1, Math.floor(phoneWidth * 0.05));
  const layers = new Array(thickness).fill(0);

  // Styles
  const containerStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: isPortrait ? "column" : "row",
    alignItems: "center",
    justifyContent: isPortrait ? "flex-start" : "center",
    width: "100%",
    height: "100%",
    fontFamily: interFamily,
    boxSizing: "border-box",
  };

  const textContainerStyle: React.CSSProperties = {
    flex: isPortrait ? 0 : 1,
    width: isPortrait ? "100%" : "auto",
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: isPortrait ? "center" : "flex-start",
    textAlign: isPortrait ? "center" : "left",
    paddingLeft: isPortrait ? 0 : width * 0.1,
    paddingTop: isPortrait ? height * 0.12 : 0,
    paddingBottom: isPortrait ? height * 0.05 : 0,
    opacity: textOpacity,
    transform: `translateX(${textTranslateX}px) translateY(${textTranslateY}px)`,
    zIndex: 10,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: isPortrait ? width * 0.12 : width * 0.06,
    fontWeight: 700,
    fontFamily: getTitleFontFamily(), 
    color: "#ffffff", // Updated to White
    marginBottom: 10,
    lineHeight: 1.1,
    letterSpacing: "-0.01em",
    maxWidth: isPortrait ? "90%" : "100%",
  };

  const subtitleStyle: React.CSSProperties = {
    fontSize: isPortrait ? width * 0.045 : width * 0.025,
    fontWeight: 400,
    color: "#b0b0b0", // Updated to Light Grey
    maxWidth: "80%",
    fontFamily: interFamily,
  };

  // Right Side (Phone 3D)
  const phoneSectionStyle: React.CSSProperties = {
    flex: isPortrait ? 1 : 1.2,
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    perspective: "2000px", 
    height: isPortrait ? "auto" : "100%",
    width: "100%",
  };

  const phoneContainerStyle: React.CSSProperties = {
    width: phoneWidth,
    height: phoneHeight,
    position: "relative",
    transformStyle: "preserve-3d",
    transform: `translateY(${phoneTranslateY}px) rotateY(${phoneRotateY}deg) rotateX(${phoneRotateX}deg) rotateZ(-2deg) scale(${phoneScale})`,
    opacity: phoneOpacity,
  };

  const basePhoneShape: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    borderRadius: phoneWidth * 0.09,
    backgroundColor: phoneBorderColor,
  };

  const frontFaceStyle: React.CSSProperties = {
    ...basePhoneShape,
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    padding: phoneWidth * 0.03,
    transform: "translateZ(0px)", 
  };

  const screenStyle: React.CSSProperties = {
    width: "100%",
    height: "100%",
    backgroundColor: "#ffffff",
    borderRadius: phoneWidth * 0.07, 
    overflow: "hidden",
    position: "relative",
  };

  const notchStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: "50%",
    transform: "translateX(-50%)",
    width: "40%",
    height: phoneHeight * 0.035,
    backgroundColor: phoneBorderColor,
    borderBottomLeftRadius: phoneWidth * 0.03,
    borderBottomRightRadius: phoneWidth * 0.03,
    zIndex: 10,
  };

  const statusBarLeft: React.CSSProperties = {
    position: "absolute",
    top: phoneHeight * 0.01,
    left: phoneWidth * 0.06,
    fontSize: phoneWidth * 0.025,
    fontWeight: 600,
    color: "#000",
    zIndex: 5,
  };
  
  const statusBarRight: React.CSSProperties = {
    position: "absolute",
    top: phoneHeight * 0.012,
    right: phoneWidth * 0.06,
    display: "flex",
    gap: phoneWidth * 0.01,
    zIndex: 5,
  };

  const dotStyle: React.CSSProperties = {
    width: phoneWidth * 0.015,
    height: phoneWidth * 0.015,
    borderRadius: "50%",
    backgroundColor: "#000",
  };

  // Generate deterministic stars for the background atmosphere
  const stars = React.useMemo(() => new Array(35).fill(0).map((_, i) => {
    const r1 = Math.sin(i * 132.1) * 43758.5453;
    const r2 = Math.cos(i * 432.1) * 12345.6789;
    const x = Math.abs(r1 % 100);
    const y = Math.abs(r2 % 100);
    const size = (Math.abs(r1 % 2.5) + 1);
    const opacity = (Math.abs(r2 % 0.6) + 0.2);
    return { x, y, size, opacity };
  }), []);

  return (
    <AbsoluteFill style={{ background: finalBg }}>
      
      {/* Background Star Field */}
      {!transparentBackground && stars.map((star, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            top: `${star.y}%`,
            left: `${star.x}%`,
            width: star.size,
            height: star.size,
            backgroundColor: "#ffffff",
            borderRadius: "50%",
            opacity: star.opacity,
            boxShadow: `0 0 ${star.size * 2}px rgba(255,255,255,0.8)`
          }}
        />
      ))}

      <div style={containerStyle}>
        
        {/* Left/Top Side: Text */}
        <div style={textContainerStyle}>
          <div style={titleStyle}>{titleText}</div>
          <div style={subtitleStyle}>{subtitleText}</div>
        </div>

        {/* Right/Bottom Side: 3D Phone */}
        <div style={phoneSectionStyle}>
          <div style={phoneContainerStyle}>
            
            {/* 3D Extrusion */}
            {layers.map((_, i) => {
                const zOffset = -(i + 1); 
                const isLast = i === thickness - 1;
                return (
                  <div
                    key={i}
                    style={{
                      ...basePhoneShape,
                      transform: `translateZ(${zOffset}px)`,
                      // For depth on dark bg, maintain phoneBorderColor but rely on shadow for contrast
                      boxShadow: isLast 
                        ? `-${phoneWidth * 0.06}px ${phoneWidth * 0.06}px ${phoneWidth * 0.12}px rgba(0,0,0,0.5)` 
                        : "none",
                    }}
                  />
                );
            })}

            {/* Front Face */}
            <div style={frontFaceStyle}>
              
              <div style={screenStyle}>
                <div style={notchStyle} />
                
                <div style={statusBarLeft}>9:41</div>
                <div style={statusBarRight}>
                   <div style={dotStyle}/>
                   <div style={dotStyle}/>
                   <div style={{...dotStyle, backgroundColor: 'transparent', border: '1px solid #000'}}/>
                </div>

                <Img 
                    src={screenshotUrl} 
                    style={{
                        width: "100%",
                        height: "100%",
                        objectFit: "cover",
                        objectPosition: "top center"
                    }}
                />
              </div>

              {/* Reflection */}
              <div style={{
                  position: 'absolute',
                  top: 0, left: 0, right: 0, bottom: 0,
                  background: 'linear-gradient(120deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 40%)',
                  borderRadius: phoneWidth * 0.09,
                  pointerEvents: 'none',
                  zIndex: 20
              }}/>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ExamSchedulePromo;